def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid separator row or column.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            a, b = grid[:r], grid[r + 1:]
            if a and b and len(a) == len(b):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(a))]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] != 0 for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and len(left[0]) == len(right[0]):
                return [[2 if left[r][j] != 0 and right[r][j] != 0 else 0
                         for j in range(len(left[0]))] for r in range(h)]

    return grid
